function check(){
	var compServiceAction = workflowData.getMetaDataMap().get("actionTakenByCompServices");
	log.info("From Top 1st split = " + compServiceAction);
	
	if(compServiceAction == "Send for Signature"){ 
               log.info("Inside if - TOP 1st split");
		return true;
	}
	else{
		return false;
	}
}

